import subprocess,json,concurrent.futures,re

def call(op,root,path=None):
    args=['python3','/tmp/tools/nas_adapter.py',op,root]+([] if path is None else [path])
    p=subprocess.run(args,capture_output=True,text=True)
    if p.returncode: raise RuntimeError(p.stderr.strip() or p.stdout.strip())
    v=json.loads(p.stdout)
    if 'error' in v: raise RuntimeError(str(v['error']))
    return v
lists={r:call('list',r) for r in ['source','destination']}
assert all(v.get('complete') is True for v in lists.values()), 'Incomplete listing'
s,d=(set(lists[r]['paths']) for r in ['source','destination'])
limitations=[]
def compare(path):
    if path not in d:return path,'source_only',None
    if path not in s:return path,'destination_only',None
    try:
        a,b=[call('stat',r,path) for r in ['source','destination']]
        if not all(type(v.get('size')) is int and v['size']>=0 for v in [a,b]):raise RuntimeError('Missing or invalid size')
        if a['size']"'!=b['"'size']:return path,'different',None
        a,b=[call('sha256',r,path) for r in ['source','destination']]
        if not all(isinstance(v.get('sha256'),str) and re.fullmatch('[0-9a-fA-F]{64}',v['sha256']) for v in [a,b]):raise RuntimeError('Missing or invalid SHA-256 digest')
        return path,('identical' if a['sha256'].lower()==b['sha256'].lower() else 'different'),None
    except Exception as e:return path,'unverified',str(e)
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:records=list(pool.map(compare,sorted(s|d)))
counts={k:sum(status==k for _,status,_ in records) for k in ['identical','different','source_only','destination_only','unverified']}
for path,status,error in records:
    if error:limitations.append(path+': '+error)
print(json.dumps({'counts':counts,'exceptions':[{'path':p,'status':s} for p,s,e in records if s"'!='"'identical'],'limitations':limitations}))
